const copy=structuredClone,sha=v=>createHash('sha256').update(v).digest('hex'),hash=v=>sha(JSON.stringify(v)),id=()=>randomBytes(32).toString('hex'),bare=v=>v.startsWith('0x')?v.slice(2):v;
