function state(account){const s=accounts.get(account);assert.ok(s&&!s.closed&&!s.poisoned,'SEPOLIA_DEFI_ORIGINAL_AUTHORITY');targetBinding(s.runtime,s.target);return s;}
async function physical(s){const d=await lstat(dirname(s.path)),p=await lstat(s.path);assert.ok(d.isDirectory()&&!d.isSymbolicLink()&&(d.mode&511)===448);assert.ok(p.isFile()&&!p.isSymbolicLink()&&p.nlink===1&&(p.mode&511)===384&&p.size>0&&p.size<=8388608);assert.equal(await realpath(dirname(s.path)),dirname(s.path));assert.equal(await realpath(s.path),s.path);if(process.getuid){assert.equal(d.uid,process.getuid());assert.equal(p.uid,process.getuid());}}
async function current(s){assert.ok(!s.closed&&!s.poisoned,'SEPOLIA_DEFI_ORIGINAL_AUTHORITY');targetBinding(s.runtime,s.target);await physical(s);assert.deepEqual(await s.vault.read(s.password),s.record,'SEPOLIA_DEFI_CURRENT_HIGH_WATER');await s.runtime.assertCanonical(s.target.finalizedHead);}
async function save(s,transform){assert.ok(s.restoring||!s.recoveryPending?.size,'SEPOLIA_DEFI_SOURCE_RECOVERY_REQUIRED');await current(s);const before=s.record,next={revision:before.revision+1,data:transform(copy(before.data))};assert.ok(Buffer.byteLength(JSON.stringify(next))<=5500000);let error;try{await s.vault.update(s.password,before.revision,()=>next.data);}catch(e){error=e;}const actual=await s.vault.read(s.password);if(isDeepStrictEqual(actual,next)){s.record=actual;await physical(s);return;}if(!isDeepStrictEqual(actual,before)){s.poisoned=true;assert.fail('SEPOLIA_DEFI_AMBIGUOUS_COMMIT');}if(error)throw error;assert.fail('SEPOLIA_DEFI_COMMIT_NOT_OBSERVED');}
async function serial(s,fn){assert.ok(!s.busy&&!s.closed&&!s.poisoned,'SEPOLIA_DEFI_BUSY_OR_CLOSED');s.busy=true;try{await current(s);return await fn();}finally{s.busy=false;}}
