function scopeReview(s,review){assert.deepEqual(review.descriptor,s.descriptor);assert.equal(review.protocol,s.binding.protocol);assert.equal(review.shareWithdrawalRecipient,s.target.account);assert.ok(![s.target.account,s.target.delivery.address,s.target.exit.address,s.target.target.pools[0].address,s.target.target.pools[1].address].includes(review.underlyingReceiver),'SEPOLIA_DEFI_USER_OUTPUT_REQUIRED');const policy=s.privateDataValidation?s.sourcePolicy:readOriginalPagedSepoliaSourceLaneV4(s.runtime).policy;assert.ok(BigInt(review.validUntil)*1000n<=BigInt(policy.expiresAt-30*60000),'SEPOLIA_DEFI_SOURCE_USABLE_DEADLINE');}
function grant(s,token){assert.ok(!s.recoveryPending?.size,'SEPOLIA_DEFI_SOURCE_RECOVERY_REQUIRED');const g=grants.get(token);assert.ok(g?.s===s,'SEPOLIA_DEFI_ORIGINAL_REVIEW_GRANT');const row=s.record.data.reviews.find(r=>r.challenge.challengeId===g.challengeId);assert.ok(row&&row.signature===g.signature,'SEPOLIA_DEFI_REVIEW_RETAINED');scopeReview(s,row.challenge.review);return row.challenge.review;}
async function ledger(s){const head=await s.runtime.block(),view=await readSepoliaDefiSharesLedgerDataV4(s.runtime,s.target,head);await current(s);return view;}
async function verifyProof(s,proof,mode){const proofKey=mode+':'+sha(Buffer.from(proof.proof,'hex'))+':'+hash(proof.publicInputs),saved=s.verifiedProofsV8?.get(proofKey);if(saved){await s.runtime.assertCanonical(saved);await current(s);return;}const a=await loadFlatVerifierArtifacts(),entry=a.verifiers[mode],rows=s.binding.parent.deployments.filter(r=>r.source===entry.source&&r.name==='HonkVerifier');assert.equal(rows.length,1,'SEPOLIA_DEFI_SAME_ORIGINAL_VERIFIER');const head=await s.runtime.block();assert.equal(await s.runtime.code(rows[0].address,head.number),rows[0].expectedCode);assert.equal(await s.runtime.call({to:rows[0].address,data:nativeProofCalldata(entry.artifact,'verify(bytes,bytes32[])',Buffer.from(proof.proof,'hex'),proof.publicInputs)},head.number),'0x'+'0'.repeat(63)+'1','SEPOLIA_DEFI_ORIGINAL_NOTE_VERIFY');await s.runtime.assertCanonical(head);await current(s);s.verifiedProofsV8??=new Map();s.verifiedProofsV8.set(proofKey,freeze(copy(head)));}
