  for(const job of s.record.data.jobs.filter(j=>j.stage==='PROVED')){const key=job.jobId+':'+job.proofSHA256;if(s.warmProofsV8?.has(key))continue;await verifyProof(s,job.proof,job.mode);if(job.mode==='deposit_intent'){const review=s.record.data.reviews.find(r=>r.challenge.review.reference===job.reviewReference).challenge.review;await s.adapter.prepareInvestment({reference:review.reference,receiptCommitment:review.receiptCommitment,proof:job.proof.proof,ownerPublicInputs:job.proof.publicInputs,maximumInputAtomic:review.maximumInputAtomic,validFrom:review.validFrom,validUntil:review.validUntil});}else s.withdrawalLedgerV8=await ledger(s);s.warmProofsV8??=new Set();s.warmProofsV8.add(key);}
