function issueConsent(s,raw){const c=raw.action==='ACCESS'?P.normalizeExternalFlatAccessV1(raw):P.normalizeExternalFlatConsentV1(raw);P.validateExternalFlatFreshV1(c);for(const [key,row]of s.challenges)if(row.consent.expiresAt<=Date.now()||row.deadline<=performance.now())s.challenges.delete(key);assert.ok(s.challenges.size<16);s.challenges.set(c.challengeId,{consent:c,checkpoint:s.financialCheckpointV8,deadline:performance.now()+Math.max(0,c.expiresAt-Date.now())});return c;}
