export async function consumeOriginalDeviceSepoliaDefiCapitalHandoffV8(runtime,token){assert.equal(arguments.length,2);const c=commands.get(token);assert.ok(c?.s.runtime===runtime&&c.kind==='INVEST'&&c.phase==='CONSUMED','SEPOLIA_DEFI_CAPITAL_CONSUMED_FINANCIAL_COMMAND');const s=c.s;return serial(s,async()=>{const j=s.record.data.jobs.find(j=>j.jobId===slots.get(c.slot).jobId);assert.equal(j.capital?.phase,'ARMED','SEPOLIA_DEFI_CAPITAL_HANDOFF_ONE_USE');assert.equal(c.revision,s.record.revision);assert.equal(c.dataSHA256,hash(s.record.data));await save(s,d=>({...d,jobs:d.jobs.map(job=>job.jobId===j.jobId?{...job,capital:{...job.capital,phase:'CONSUMED'}}:job)}));c.revision=s.record.revision;c.dataSHA256=hash(s.record.data);return freeze(copy(s.record.data.jobs.find(job=>job.jobId===j.jobId).capital));});}
/** Canonical private-share delivery is observed from this account's own
 * retained action and transaction; caller receipts cannot create evidence. */
export async function readOriginalDeviceSepoliaDefiDeliveryEvidenceV8(account,jobId){assert.equal(arguments.length,2);const s=state(account);return serial(s,async()=>{P.externalFlatHexV1(jobId);const job=s.record.data.jobs.find(j=>j.jobId===jobId);assert.ok(job?.mode==='deposit_intent'&&job.stage==='CONFIRMED'&&job.submission?.transactionHash,'SEPOLIA_DEFI_ORIGINAL_CONFIRMED_DELIVERY');const row=s.record.data.reviews.find(r=>r.challenge.review.reference===job.reviewReference);assert.equal(row?.challenge.review.action,'INVEST');verifySignature(s.descriptor,R.deviceSepoliaDefiReviewPermissionMessageV4(row.challenge),row.signature);const observed=await s.adapter.observe(job.reviewReference);assert.equal(observed.phase,'CONFIRMED');assert.equal(observed.kind,'INVEST');assert.equal(observed.nativeId,job.submission.transactionHash);assert.equal(observed.shares,row.challenge.review.shares);assert.equal(observed.ownerOutput,job.consent.statement.output);return freeze({protocol:s.binding.protocol,jobId,reference:job.reviewReference,transactionHash:observed.nativeId,descriptor:observed.descriptor,receiptCommitment:row.challenge.review.receiptCommitment,shareAmount:row.challenge.review.shares,inputSpent:observed.observedInputAtomic,underlyingAssetIdentity:bare(s.target.target.pools[0].assetIdentity),shareAssetIdentity:bare(s.target.target.pools[1].assetIdentity)});});}

